import { FunctionalComponent, h } from 'preact';

import CircularProgress from '@material-ui/core/CircularProgress';
import HighlightOffIcon from '@material-ui/icons/HighlightOff';
import CheckCircleOutlineIcon from '@material-ui/icons/CheckCircleOutline';

import styles from './styles.module.scss';

const ICONS = {
  loading: CircularProgress,
  success: CheckCircleOutlineIcon,
  error: HighlightOffIcon,
};

export type StateIndicatorPropsType = 'loading' | 'success' | 'error';

interface StateIndicatorProps {
  type: StateIndicatorPropsType;
  message?: string;
  className?: string;
  style?: string | h.JSX.CSSProperties;
}

const StateIndicator: FunctionalComponent<StateIndicatorProps> = ({
  type,
  message,
  className,
  style,
}: StateIndicatorProps) => {
  const Icon = ICONS[type];

  return (
    <div
      style={style}
      className={`${styles.spinnerContainer} ${styles[type]} ${className}`}
    >
      <Icon />
      {message && <p className={styles.spinnerMessage}>{message}</p>}
    </div>
  );
};

StateIndicator.defaultProps = {
  style: '',
};

export default StateIndicator;
